P=Path(__file__).resolve().parent
ROOT=P.parents[1]
G={}
def group(name, cases):
 G[name]=[dict(id=f'F{sum(map(len,G.values()))+i+1:02}',city=city,question=q,expected=e,**({'image':img} if img else {})) for i,(city,q,e,img) in enumerate(cases)]
def c(city,q,e,img=None):return city,q,e,img
